arguments.command:
curl -s "https://exoplanetarchive.ipac.caltech.edu/TAP/sync?query=select+pl_name,pl_masse,pl_orbper,pl_orbeccen,disc_year,disc_facility+from+ps+where+discoverymethod='Radial+Velocity'+and+pl_masse%3E0+and+pl_masse%3C%3D5+and+pl_orbper%3E%3D100+order+by+pl_orbeccen+desc&format=csv" 2>/dev/null | python3 -c "
import csv, sys
reader = csv.DictReader(sys.stdin)
for row in reader:
    if row['pl_masse'] and row['pl_orbper'] and row['pl_orbeccen']:
        try:
            mass = float(row['pl_masse'])
            per = float(row['pl_orbper'])
            ecc = float(row['pl_orbeccen'])
            year = int(row['disc_year']) if row['disc_year'] else 0
            if mass <= 5 and per >= 100 and year < 2020:
                print(f\"{row['pl_name']}: mass={mass}, period={per}, ecc={ecc}, year={year}, facility={row['disc_facility']}\")
        except:
            pass
" | head -20
